import toPath from 'lodash/toPath'
import {useCallback, useMemo, useState} from 'react'
import {graphql, useMutation, usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useAppDispatch} from '../../../../hooks/react-redux'
import {useOnDemandQuery} from '../../../../hooks/relay/useOnDemandQuery'
import {extractErrorFromRelay} from '../../../../relay/extractErrorFromRelay'
import {BS} from '../../../../types/BS_types'
import {emptyMap} from '../../../../utils/empty'
import {storeDslFragment} from '../../Dsl/Dsl.actions'
import type {MatrixParamBuildProjectsDefaultValueSetsQuery} from '../__generated__/MatrixParamBuildProjectsDefaultValueSetsQuery.graphql'
import type {MatrixParamBuildQuery} from '../__generated__/MatrixParamBuildQuery.graphql'
import {projectsDefaultValueSetsQuery, matrixQuery} from '../MatrixParamBuild.queries'
import type {MatrixParamBuildFeature} from '../MatrixParamBuild.types'

import type {useMatrixParamBuildAddMatrixMutation} from './__generated__/useMatrixParamBuildAddMatrixMutation.graphql'
import type {useMatrixParamBuildMatrixAsCodeQuery} from './__generated__/useMatrixParamBuildMatrixAsCodeQuery.graphql'
import type {useMatrixParamBuildUpdateMatrixMutation} from './__generated__/useMatrixParamBuildUpdateMatrixMutation.graphql'

const addMatrixMutation = graphql`
  mutation useMatrixParamBuildAddMatrixMutation($btLocator: String!, $input: MatrixFeatureInput) {
    addBuildTypeMatrix(btLocator: $btLocator, input: $input) {
      count
    }
  }
`

const updateMatrixMutation = graphql`
  mutation useMatrixParamBuildUpdateMatrixMutation(
    $btLocator: String!
    $featureId: String!
    $input: MatrixFeatureInput
  ) {
    updateBuildTypeMatrix(btLocator: $btLocator, featureId: $featureId, input: $input) {
      count
    }
  }
`

const matrixAsCodeQuery = graphql`
  query useMatrixParamBuildMatrixAsCodeQuery($btLocator: String!, $input: MatrixAsCodeInput!) {
    buildTypeMatrixAsCode(btLocator: $btLocator, input: $input) {
      entityConfig
      before
      after
    }
  }
`

function useMatrixParamBuild(
  buildTypeId: string,
  projectId: string,
  queryRef: PreloadedQuery<MatrixParamBuildQuery>,
  defaultValueSetsQueryRef: PreloadedQuery<MatrixParamBuildProjectsDefaultValueSetsQuery>,
  featureId = '',
  featureType = '',
  readOnly?: string,
) {
  const dispatch = useAppDispatch()
  const isCreateMode = !featureId
  const {buildTypeMatrix = null} = usePreloadedQuery(matrixQuery, queryRef)
  const featureViewAsCode =
    useOnDemandQuery<useMatrixParamBuildMatrixAsCodeQuery>(matrixAsCodeQuery)
  const [errors, setErrors] = useState<Record<string, string>[]>()
  const [addMatrix] = useMutation<useMatrixParamBuildAddMatrixMutation>(addMatrixMutation)
  const [updateMatrix] = useMutation<useMatrixParamBuildUpdateMatrixMutation>(updateMatrixMutation)
  const data = usePreloadedQuery(projectsDefaultValueSetsQuery, defaultValueSetsQueryRef)
  const projectsDefaultValueSets = data.projectsDefaultValueSets?.valueSet ?? []
  const matrixParamBuildSubmitHandler = useCallback(
    (feature: MatrixParamBuildFeature) =>
      (isCreateMode ? addMatrix : updateMatrix)({
        variables: {
          btLocator: `id:${buildTypeId}`,
          featureId,
          input: {parameters: feature.parameters, separateArtifacts: feature.separateArtifacts},
        },
        onCompleted: () => {
          BS?.BuildFeatureDialog?.close()
          BS?.reload?.(true)
        },
        onError: e => setErrors(JSON.parse(extractErrorFromRelay(e).message).error),
      }),
    [addMatrix, buildTypeId, featureId, isCreateMode, updateMatrix],
  )
  const matrixParamBuildViewAsCodeSubmitHandler = useCallback(
    async (feature: MatrixParamBuildFeature, version: string, portable: boolean) => {
      const matrixFeatureId = featureId || null
      const params = {
        btLocator: buildTypeId,
        input: {
          featureType,
          featureId: matrixFeatureId,
          showDSL: 'item',
          showDSLVersion: version,
          showDSLPortable: portable,
          descriptor: {
            parameters: feature.parameters,
            separateArtifacts: feature.separateArtifacts,
          },
        },
      }
      try {
        const {buildTypeMatrixAsCode} = (await featureViewAsCode(params).toPromise()) ?? {}
        if (buildTypeMatrixAsCode != null) {
          dispatch(storeDslFragment(buildTypeMatrixAsCode))
        }
      } catch (e) {
        if (e instanceof Error) {
          setErrors(JSON.parse(extractErrorFromRelay(e).message).error)
        }
        throw e
      }
    },
    [buildTypeId, dispatch, featureId, featureType, featureViewAsCode],
  )
  const errorMessages = useMemo(() => {
    if (errors?.length) {
      return errors.reduce<Map<string, string>>((accumulator, value) => {
        const {message, location} = value
        const [_, ...restPath] = toPath(location)
        const isErrorParameterSection = restPath.length === 1
        const errorPath = isErrorParameterSection ? [...restPath, 'name'] : restPath
        const pathField = errorPath
          .map(path => (!isNaN(Number(path)) ? `[${path}]` : path))
          .join('.')

        accumulator.set(pathField, message)

        return accumulator
      }, new Map())
    }

    return emptyMap
  }, [errors])
  const isReadOnlyMode = readOnly === 'true'

  return {
    errorMessages,
    isReadOnlyMode,
    matrixKey: buildTypeMatrix,
    projectsDefaultValueSets,
    matrixParamBuildSubmitHandler,
    matrixParamBuildViewAsCodeSubmitHandler,
  }
}

export default useMatrixParamBuild
