import trashIcon from '@jetbrains/icons/trash.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'

import {emptyArray} from '../../../../utils/empty'
import {isMatrixSeparateArtifactsEnabled} from '../MatrixParamBuild.consts'
import styles from '../MatrixParamBuild.module.css'
import MatrixParamBuildParameterValues from '../MatrixParamBuildParameterValues/MatrixParamBuildParameterValues'
import MatrixParamBuildSeparateArtifacts from '../MatrixParamBuildSeparateArtifacts/MatrixParamBuildSeparateArtifacts'

import MatrixParamBuildParameterSelect from './MatrixParamBuildParameterSelect/MatrixParamBuildParameterSelect'
import useMatrixParamBuildParameters from './useMatrixParamBuildParameters'

type MatrixParamBuildParametersRrops = {
  isReadOnlyMode: boolean
}

function MatrixParamBuildParameters({isReadOnlyMode}: MatrixParamBuildParametersRrops) {
  const {
    feature,
    isAllowDelete,
    restoreParameters,
    parameterDuplicates,
    parameterSelectOptions,
    parameterValuesOptions,
    latestInputParamNameRef,
    clickAddParameterButtonHandler,
    deleteParameterButtonClickHandler,
    restoreParameterButtonClickHandler,
    deletePermanentlyParameterButtonClickHandler,
    parameterSelectHints,
  } = useMatrixParamBuildParameters()

  return (
    <div className={styles.form}>
      {feature.parameters.map((parameter, index) => {
        const deletedParameterName = restoreParameters[index]
        const parametersLength = feature.parameters.length
        const key = `${index}-${parametersLength}`

        if (parameter?.name == null && !deletedParameterName?.name) {
          return null
        }

        if (parameter?.name == null) {
          const restoreParameterName =
            parameterValuesOptions.get(deletedParameterName!.name ?? '')?.displayName ??
            deletedParameterName?.name

          return (
            <div className={styles.restore} key={key}>
              {`You have deleted the parameter <${restoreParameterName}>. Do you want to restore it?`}
              <div>
                <Button inline onClick={restoreParameterButtonClickHandler(index)}>
                  {'Restore'}
                </Button>

                <Button
                  className={styles.restoreDeletePermanently}
                  primary
                  inline
                  onClick={deletePermanentlyParameterButtonClickHandler(index)}
                >
                  {'Delete permanently'}
                </Button>
              </div>
            </div>
          )
        }
        const isDuplicate = Boolean(parameterDuplicates.get(parameter.name ?? ''))
        const parameterValuesSelectOptions = parameterValuesOptions.get(parameter.name ?? '')
        const parameterHint = parameterSelectHints.get(parameter.name ?? '')
        const isLast = index === parametersLength - 1
        const matrixParamBuildParameterSelectRef = isLast ? latestInputParamNameRef : null

        return (
          <div key={key} className={styles.parameter}>
            <div className={styles.parameterName}>
              <div className={styles.row}>
                <MatrixParamBuildParameterSelect
                  options={parameterSelectOptions}
                  isDuplicate={isDuplicate}
                  value={parameter.name}
                  index={index}
                  hint={parameterHint}
                  disabled={isReadOnlyMode}
                  ref={matrixParamBuildParameterSelectRef}
                />
                {isAllowDelete && (
                  <Button
                    onClick={deleteParameterButtonClickHandler(parameter, index)}
                    icon={trashIcon}
                    title="Delete parameter"
                    disabled={isReadOnlyMode}
                  />
                )}
              </div>
            </div>

            <MatrixParamBuildParameterValues
              parameterIndex={index}
              options={parameterValuesSelectOptions?.value}
              values={parameter.value ?? emptyArray}
              disabled={isReadOnlyMode}
            />
          </div>
        )
      })}
      <Button onClick={clickAddParameterButtonHandler} disabled={isReadOnlyMode}>
        {'Add parameter'}
      </Button>
      {isMatrixSeparateArtifactsEnabled && (
        <MatrixParamBuildSeparateArtifacts feature={feature} disabled={isReadOnlyMode} />
      )}
    </div>
  )
}

export default MatrixParamBuildParameters
