import Toggle, {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'

import {useMatrixParamBuildContext} from '../contexts/MatrixParamBuildContext'
import styles from '../MatrixParamBuild.module.css'

import type {MatrixParamBuildSeparateArtifactsProps} from './MatrixParamBuildSeparateArtifacts.types'

function MatrixParamBuildSeparateArtifacts({
  feature,
  disabled,
}: MatrixParamBuildSeparateArtifactsProps) {
  const {changeSeparateArtifactsHandler} = useMatrixParamBuildContext()

  return (
    <div className={styles.buttonClassName}>
      <Toggle
        onChange={changeSeparateArtifactsHandler}
        checked={feature.separateArtifacts}
        disabled={disabled}
        size={Size.Size20}
      >
        {'Distribute artifacts in separate folders in main build'}
      </Toggle>
    </div>
  )
}

export default MatrixParamBuildSeparateArtifacts
