import HelpIcon from '@jetbrains/icons/help.svg'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import type {EntryPointProps} from 'react-relay'

import {resolveHelpURL} from '../../../utils/url'

import type {MatrixParamBuildProjectsDefaultValueSetsQuery} from './__generated__/MatrixParamBuildProjectsDefaultValueSetsQuery.graphql'
import type {MatrixParamBuildQuery} from './__generated__/MatrixParamBuildQuery.graphql'
import MatrixParamBuildProvider from './contexts/MatrixParamBuildContext'
import MatrixParamBuildErrorProvider from './contexts/MatrixParamBuildErrorContext'
import useMatrixParamBuild from './hooks/useMatrixParamBuild'
import type {MatrixParamBuildProps} from './MatrixParamBuild.types'
import MatrixParamBuildParameters from './MatrixParamBuildParameters/MatrixParamBuildParameters'

import styles from './MatrixParamBuild.module.css'

type Queries = {
  main: MatrixParamBuildQuery
  defaultValueSets: MatrixParamBuildProjectsDefaultValueSetsQuery
}

function MatrixParamBuild({
  queries,
  props,
}: EntryPointProps<Queries, {}, MatrixParamBuildProps, {}>) {
  const {buildTypeId, projectId, featureId, featureType, readOnly} = props
  const {
    isReadOnlyMode,
    errorMessages,
    matrixKey,
    projectsDefaultValueSets,
    matrixParamBuildSubmitHandler,
    matrixParamBuildViewAsCodeSubmitHandler,
  } = useMatrixParamBuild(
    buildTypeId,
    projectId,
    queries.main,
    queries.defaultValueSets,
    featureId,
    featureType,
    readOnly,
  )

  return (
    <MatrixParamBuildErrorProvider isReadOnlyMode={isReadOnlyMode} externalErrors={errorMessages}>
      <div className={styles.description}>
        {'Iterates over parameter values and creates a separate build for every combination'}
        <Link
          aria-label="Help"
          target={'_blank'}
          rel={'noreferrer'}
          href={resolveHelpURL('matrix-build.html')}
        >
          <SvgIcon className={styles.helpIcon} icon={HelpIcon} />
        </Link>
      </div>
      <MatrixParamBuildProvider
        buildTypeId={buildTypeId}
        onSubmit={matrixParamBuildSubmitHandler}
        onViewAsCodeSubmit={matrixParamBuildViewAsCodeSubmitHandler}
        options={projectsDefaultValueSets}
        matrixKey={matrixKey}
      >
        <MatrixParamBuildParameters isReadOnlyMode={isReadOnlyMode} />
      </MatrixParamBuildProvider>
    </MatrixParamBuildErrorProvider>
  )
}

export default MatrixParamBuild
export type MatrixParamBuildComponent = typeof MatrixParamBuild
