import {castDraft, produce} from 'immer'

import cloneDeep from 'lodash/cloneDeep'
import type {ChangeEvent} from 'react'
import {
  useState,
  createContext,
  memo,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
} from 'react'
import {graphql, useFragment} from 'react-relay'

import {BS} from '../../../../types/BS_types'
import {defaultMatrixBuildFeature} from '../MatrixParamBuild.consts'
import type {
  MatrixParamBuildFeature,
  MatrixParamBuildParameter,
  SelectItemMatrixParameter,
} from '../MatrixParamBuild.types'

import type {
  MatrixParamBuildContextProps,
  MatrixParamBuildProviderProps,
} from './MatrixParamBuildContext.types'
import {useMatrixParamBuildError} from './MatrixParamBuildErrorContext'

const MatrixParamBuildContext = createContext<MatrixParamBuildContextProps>(
  {} as MatrixParamBuildContextProps,
)

export const useMatrixParamBuildContext = () => useContext(MatrixParamBuildContext)

const matrixFragment = graphql`
  fragment MatrixParamBuildContext_matrix on MatrixFeature {
    parameters {
      name
      value {
        value
        label
      }
    }
    separateArtifacts
  }
`

function MatrixParamBuildProvider({
  options,
  onSubmit,
  onViewAsCodeSubmit,
  children,
  buildTypeId,
  matrixKey,
}: MatrixParamBuildProviderProps) {
  const fragment = useFragment(matrixFragment, matrixKey)
  const data = {
    parameters: fragment?.parameters ?? defaultMatrixBuildFeature.parameters,
    separateArtifacts: fragment?.separateArtifacts ?? defaultMatrixBuildFeature.separateArtifacts,
  }
  const elementSaveButtonRef = useRef<HTMLInputElement | undefined>(
    BS?.BuildFeatureDialog?.getSaveButton(),
  )
  const {hasFieldsHideErrorHandler} = useMatrixParamBuildError()
  const [feature, setFeature] = useState<MatrixParamBuildFeature>(cloneDeep(castDraft(data)))
  const restoreParametersRef = useRef<Record<string, MatrixParamBuildParameter | undefined>>({})
  const restoreParameters = restoreParametersRef.current
  const parametersNameSet = useMemo(
    () => new Set(feature?.parameters?.map(parameter => parameter?.name)),
    [feature],
  )
  const parameterSelectHints = useMemo(() => new Map<string, string | null | undefined>(), [])
  const parameterSelectOptions = useMemo(
    () =>
      options.reduce<SelectItemMatrixParameter[]>((accumulator, parameter) => {
        const {description} = parameter
        const label = parameter.name ?? ''
        const isDuplicate = parametersNameSet.has(parameter.name)
        if (!isDuplicate) {
          const keyword = [label, label, ...(parameter?.keyword ?? [])]
          accumulator.push({
            label,
            key: label,
            keyword,
            details: parameter?.description,
          })
        }

        parameterSelectHints.set(label, description)

        return accumulator
      }, []),
    [options, parameterSelectHints, parametersNameSet],
  )
  const parameterValuesOptions = useMemo(
    () =>
      options.reduce((accumulator, parameter) => {
        accumulator.set(parameter.name ?? '', {
          ...parameter,
          value:
            parameter?.value?.map(({value, label}) => {
              const labelKey = label ? `${label}=>` : ''
              const key = `${labelKey}${value}`

              return {
                key,
                label: key,
              }
            }) ?? [],
        })

        return accumulator
      }, new Map()),
    [options],
  )
  const parameterDuplicates = useMemo(
    () =>
      feature?.parameters?.reduce<Map<string, number>>((accumulator, parameter) => {
        const parameterName = parameter?.name
        if (parameterName) {
          let amount = accumulator.get(parameterName)
          accumulator.set(parameterName, typeof amount === 'number' ? ++amount : 0)
        }

        return accumulator
      }, new Map()),
    [feature],
  )
  const deleteParameterHandler = useCallback(
    (parameter: MatrixParamBuildParameter, index: number) => {
      restoreParameters[index] = parameter

      setFeature(state =>
        produce(state, draft => {
          draft.parameters[index] = {
            name: null,
            value: null,
          }
        }),
      )
    },
    [restoreParameters],
  )
  const restoreParameterHandler = useCallback(
    (index: number) => {
      const restoredParameter = restoreParameters[index]

      restoreParameters[index] = undefined

      if (restoredParameter) {
        setFeature(state =>
          produce(state, draft => {
            draft.parameters[index] = restoredParameter
          }),
        )
      }
    },
    [restoreParameters],
  )
  const deletePermanentlyParameterHandler = useCallback(
    (index: number) => {
      restoreParameters[index] = undefined

      setFeature(state =>
        produce(state, draft => {
          delete draft.parameters[index]
        }),
      )
    },
    [restoreParameters],
  )
  const addParameterHandler = useCallback(() => {
    setFeature(state =>
      produce(state, draft => {
        draft.parameters = [...draft.parameters, cloneDeep(defaultMatrixBuildFeature.parameters[0])]
      }),
    )
  }, [])
  const addParameterValueHandler = useCallback(
    (index: number) => {
      const parameterValues = feature.parameters[index]?.value
      if (parameterValues != null) {
        setFeature(state =>
          produce(state, draft => {
            draft.parameters[index] ??= {}
            draft.parameters[index]!.value ??= []
            draft.parameters[index]!.value!.push({
              value: '',
            })
          }),
        )
      }
    },
    [feature],
  )
  const deleteParameterValueHandler = useCallback(
    (parameterIndex: number, index: number) => {
      const parameterValues = feature.parameters[parameterIndex]?.value

      if (parameterValues != null) {
        setFeature(state =>
          produce(state, draft => {
            const parameter = draft.parameters[parameterIndex]
            if (parameter != null && 'value' in parameter) {
              parameter.value = parameterValues.filter((_, indexValue) => indexValue !== index)
            }
          }),
        )
      }
    },
    [feature],
  )
  const saveButtonClickHandler = useCallback(
    (event: MouseEvent) => {
      const hasHideError = hasFieldsHideErrorHandler()

      event.stopPropagation()
      event.preventDefault()

      if (!hasHideError) {
        const saveParameters = feature.parameters.filter(
          (parameter): parameter is MatrixParamBuildParameter => parameter?.name != null,
        )
        const saveFeature = {
          parameters: saveParameters,
          separateArtifacts: feature.separateArtifacts,
        }
        onSubmit(saveFeature)
      }
    },
    [hasFieldsHideErrorHandler, onSubmit, feature],
  )
  const viewAsCodeHandler = useCallback(
    async (version: string, portable: boolean) => {
      const saveParameters = feature.parameters.filter(
        (parameter): parameter is MatrixParamBuildParameter => parameter?.name != null,
      )
      const saveFeature = {
        parameters: saveParameters,
        separateArtifacts: feature.separateArtifacts,
      }

      return await onViewAsCodeSubmit(saveFeature, version, portable)
    },
    [onViewAsCodeSubmit, feature],
  )

  const changeSeparateArtifactsHandler = useCallback((event: ChangeEvent<HTMLInputElement>) => {
    const {checked} = event.target
    setFeature(state =>
      produce(state, draft => {
        draft.separateArtifacts = checked
      }),
    )
  }, [])

  const valueContext = useMemo(
    () => ({
      feature,
      buildTypeId,
      restoreParameters,
      parameterSelectOptions,
      parameterValuesOptions,
      parameterDuplicates,
      parameterSelectHints,
      setFeature,
      addParameterHandler,
      deleteParameterHandler,
      restoreParameterHandler,
      addParameterValueHandler,
      deleteParameterValueHandler,
      deletePermanentlyParameterHandler,
      changeSeparateArtifactsHandler,
    }),
    [
      addParameterHandler,
      addParameterValueHandler,
      buildTypeId,
      deleteParameterHandler,
      deleteParameterValueHandler,
      deletePermanentlyParameterHandler,
      parameterDuplicates,
      parameterSelectOptions,
      parameterValuesOptions,
      feature,
      parameterSelectHints,
      restoreParameterHandler,
      restoreParameters,
      changeSeparateArtifactsHandler,
    ],
  )

  useEffect(() => {
    const elementSaveButton = elementSaveButtonRef.current

    elementSaveButton?.addEventListener('click', saveButtonClickHandler)
    BS?.BuildFeatureDialog?.recenterDialog()
    BS?.EditDsl?.setCustomLoadDslFragment(viewAsCodeHandler)

    return () => {
      elementSaveButton?.removeEventListener('click', saveButtonClickHandler)
    }
  }, [elementSaveButtonRef, saveButtonClickHandler, viewAsCodeHandler])

  return (
    <MatrixParamBuildContext.Provider value={valueContext}>
      {children}
    </MatrixParamBuildContext.Provider>
  )
}

export default memo(MatrixParamBuildProvider)
