import {produce} from 'immer'

import toPath from 'lodash/toPath'

import {useMatrixParamBuildContext} from '../contexts/MatrixParamBuildContext'
import {useMatrixParamBuildError} from '../contexts/MatrixParamBuildErrorContext'
import type {MatrixParamBuildValues} from '../MatrixParamBuild.types'

function useMatrixParamBuildFieldControl(fieldName: string) {
  const fieldPath = toPath(fieldName)
  const {feature, buildTypeId, setFeature} = useMatrixParamBuildContext()
  const {fieldErrorMessage, setHideErrorHandler, ...restContext} = useMatrixParamBuildError()
  const errorMessage = fieldErrorMessage[fieldName]
  const isFieldTouched = fieldName in fieldErrorMessage
  const changeValueHandler = (value: MatrixParamBuildValues) => {
    const [pathParameterIndex, _, valueIndex] = fieldPath
    const parameterIndex = Number(pathParameterIndex)
    const parameter = feature.parameters[parameterIndex]

    if (parameter) {
      setFeature(state =>
        produce(state, draft => {
          const draftParameter = draft?.parameters[parameterIndex]

          if (draftParameter?.value != null) {
            const newParameterValues = draftParameter.value

            newParameterValues[Number(valueIndex)] = value

            draftParameter.value = newParameterValues
          }
        }),
      )
    }
  }
  const changeParameterHandler = (name: string) => {
    const [index] = fieldPath
    const parameter = feature.parameters[Number(index)]

    if (parameter) {
      setFeature(state =>
        produce(state, draft => {
          draft.parameters[Number(index)] = {
            name,
            value: parameter.value,
          }
        }),
      )
    }
  }

  return {
    errorMessage,
    isFieldTouched,
    buildTypeId,
    changeValueHandler,
    changeParameterHandler,
    setHideErrorHandler,
    ...restContext,
  }
}

export default useMatrixParamBuildFieldControl
